sap.ui.define([
    "sap/ui/core/UIComponent",
    "ns/html5module/model/models"
], (UIComponent, models) => {
    "use strict";

    return UIComponent.extend("ns.html5module.Component", {
        metadata: {
            manifest: "json",
            interfaces: [
                "sap.ui.core.IAsyncContentCreation"
            ]
        },

        init() {
            // call the base component's init function
            UIComponent.prototype.init.apply(this, arguments);

            // set the device model
            this.setModel(models.createDeviceModel(), "device");

            // enable routing
            this.getRouter().initialize();
        }
    });
});

sap.ui.define([
    "sap/ui/model/json/JSONModel",
    "sap/ui/Device"
], 
function (JSONModel, Device) {
    "use strict";

    return {
        /**
         * Provides runtime information for the device the UI5 app is running on as a JSONModel.
         * @returns {sap.ui.model.json.JSONModel} The device model.
         */
        createDeviceModel: function () {
            var oModel = new JSONModel(Device);
            oModel.setDefaultBindingMode("OneWay");
            return oModel;
        }
    };

});

sap.ui.define([
    "../localService/mockserver",
    "sap/m/MessageBox"
], function (mockserver, MessageBox) {
    "use strict";

    var aMockservers = [];

    // initialize the mock server
    aMockservers.push(mockserver.init());

    Promise.all(aMockservers).catch(function (oError) {
        MessageBox.error(oError.message);
    }).finally(function () {
        // initialize the embedded component on the HTML page
        sap.ui.require(["sap/ui/core/ComponentSupport"]);
    });
});

/*global QUnit*/
sap.ui.define([
    "sap/ui/test/opaQunit",
    "ns/html5module/test/integration/pages/View1",
    "ns/html5module/test/integration/arrangements/Startup"
], function(opaTest) {
    "use strict";

    QUnit.module("Navigation Journey");

    // TC-013: OPA5 integration test — intentionally fails due to Chrome 94 + latest UI5 incompatibility
    // This demonstrates failure reporting in the XML
    opaTest("Should see the initial page of the app", function(Given, When, Then) {
        Given.iStartMyApp();
        Then.onView1.iShouldSeeTheApp();
        Then.iTeardownMyApp();
    });
});

sap.ui.define([
	"sap/ui/test/Opa5"
], function (Opa5) {
	"use strict";

	return Opa5.extend("ns.html5module.test.integration.arrangements.Startup", {

		iStartMyApp: function (oOptionsParameter) {
			var oOptions = oOptionsParameter || {};

			// start the app with a minimal delay to make tests fast but still async to discover basic timing issues
			oOptions.delay = oOptions.delay || 50;

			// start the app UI component
			this.iStartMyUIComponent({
				componentConfig: {
					name: "ns.html5module",
					async: true
				},
				hash: oOptions.hash,
				autoWait: oOptions.autoWait
			});
		}
	});
});

/* global QUnit */
QUnit.config.autostart = false;

sap.ui.getCore().attachInit(function () {
	"use strict";

	sap.ui.require([
		"ns/html5module/test/integration/AllJourneys"
	], function () {
		QUnit.start();
	});
});

sap.ui.define([
	"sap/ui/test/Opa5"
], function (Opa5) {
	"use strict";
	var sViewName = "View1";
	Opa5.createPageObjects({
		onTheAppPage: {

			actions: {},

			assertions: {

				iShouldSeeTheApp: function () {
					return this.waitFor({
						id: "app",
						viewName: sViewName,
						success: function () {
							Opa5.assert.ok(true, "The " + sViewName + " view is displayed");
						},
						errorMessage: "Did not find the " + sViewName + " view"
					});
				}
			}
		}
	});

});

/* global window, parent, location */

// eslint-disable-next-line sap-no-global-define
window.suite = function() {
	"use strict";

	// eslint-disable-next-line
	var oSuite = new parent.jsUnitTestSuite(),
		sContextPath = location.pathname.substring(0, location.pathname.lastIndexOf("/") + 1);

	oSuite.addTestPage(sContextPath + "unit/unitTests.qunit.html");
	oSuite.addTestPage(sContextPath + "integration/opaTests.qunit.html");

	return oSuite;
};

/*global QUnit*/
sap.ui.define([
    "sap/ui/core/mvc/Controller",
    "ns/html5module/controller/View1.controller"
], function(Controller, View1Controller) {
    "use strict";

    QUnit.module("View1 Controller", {
        beforeEach: function() {
            this.oController = new View1Controller();
        },
        afterEach: function() {
            this.oController.destroy();
        }
    });

    // TC-001: Passes
    QUnit.test("I should test the View1 controller", function(assert) {
        assert.ok(this.oController, "Controller instance created successfully");
    });

    // TC-002: Passes
    QUnit.test("Controller should have an onInit function", function(assert) {
        assert.ok(typeof this.oController.onInit === "function", "onInit is defined");
    });

    // TC-003: Passes
    QUnit.test("Controller metadata should have correct type", function(assert) {
        assert.strictEqual(
            this.oController.getMetadata().getName(),
            "ns.html5module.controller.View1",
            "Controller name matches"
        );
    });

    // TC-004: Passes
    QUnit.test("Controller should extend sap.ui.core.mvc.Controller", function(assert) {
        assert.ok(
            this.oController instanceof Controller,
            "Controller is an instance of sap.ui.core.mvc.Controller"
        );
    });

    // TC-005: Intentional failure — demonstrates failure reporting
    QUnit.test("Controller display name should match expected value (intentional fail)", function(assert) {
        assert.strictEqual(
            this.oController.getMetadata().getName(),
            "ns.html5module.controller.WrongName",
            "This test intentionally fails to demonstrate failure reporting"
        );
    });

    // TC-006: Passes
    QUnit.test("Controller should be destroyable", function(assert) {
        var oNew = new View1Controller();
        oNew.destroy();
        assert.ok(true, "Controller destroyed without error");
    });
});

/*global QUnit*/
sap.ui.define([
    "ns/html5module/model/models"
], function(models) {
    "use strict";

    QUnit.module("Model Utilities");

    // TC-007: Passes
    QUnit.test("createDeviceModel should return a JSONModel", function(assert) {
        var oModel = models.createDeviceModel();
        assert.ok(oModel, "Device model created successfully");
        oModel.destroy();
    });

    // TC-008: Passes
    QUnit.test("Device model should have isMobile property", function(assert) {
        var oModel = models.createDeviceModel();
        var bIsMobile = oModel.getProperty("/system/phone");
        assert.strictEqual(typeof bIsMobile, "boolean", "isMobile is a boolean");
        oModel.destroy();
    });

    // TC-009: Intentional failure — demonstrates failure in model tests
    QUnit.test("Device model version should match (intentional fail)", function(assert) {
        assert.strictEqual("1.0", "2.0", "This test intentionally fails");
    });
});

/*global QUnit*/
sap.ui.define([], function() {
    "use strict";

    QUnit.module("Formatter Utilities");

    // TC-010: Passes
    QUnit.test("Empty string should be treated as falsy", function(assert) {
        assert.notOk("", "Empty string is falsy");
    });

    // TC-011: Passes
    QUnit.test("Non-empty string should be truthy", function(assert) {
        assert.ok("hello", "Non-empty string is truthy");
    });

    // TC-012: Passes — demonstrates skipped via assert.expect
    QUnit.test("Numeric zero should be falsy", function(assert) {
        assert.notOk(0, "Zero is falsy");
    });
});
